item.command:
/bin/zsh -lc "set -u
CLI=.qfactory/tools/qloops-0.2.0-core.9/node_modules/.bin/qloops
printf '%s\\n' '--- independent successful-result check ---'
node verify-service-readiness.mjs .qf/last-run.json
printf '%s\\n' '--- negative run (expected failure) ---'
set +e
\""'$CLI" run service-readiness-negative.yaml --json | tee /private/tmp/qfactory-session-20260910/service-readiness-negative-run.json
negative_exit=${pipestatus[1]}
set -e
echo "negative_exit=$negative_exit"
printf '"'%s\\n' '--- negative retained evidence ---'
sed -n '1,220p' .qf/last-run.json
negative_run="'$(node -e '"'process.stdout.write(JSON.parse(require(\"fs\").readFileSync(\".qf/last-run.json\",\"utf8\")).runId)')
sed -n '1,280p' \".qf/runs/"'$negative_run.json"
node - "$negative_run" <<'"'NODE'
const fs=require('fs');
const id=process.argv[2];
const e=JSON.parse(fs.readFileSync('.qf/runs/'+id+'.json','utf8'));
if (e.status "'!== '"'failed') throw new Error('negative run did not fail');
if ("'!e.steps?.some(s => s.stepId === '"'fail' && s.status === 'failed' && /422/.test(s.errorText || ''))) {
  throw new Error('negative run lacked visible HTTP 422 failure');
}
console.log(JSON.stringify({checked:true,status:e.status,failedStep:'fail',error:e.steps.find(s=>s.stepId==='fail').errorText}));
NODE
exit 0"

